{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration/1e6,0.5),1) p50_ms, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' GROUP BY 1",
          "claim": "In the abnormal period the order-other DB client span 'SELECT ts.orders_other' has p95 around 400+ms, with no child spans, so the time is inside the DB call."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'norm' p, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('OrderOtherRepository.findByAccountId','OrderOtherRepository.findAll','OrderOtherRepository.findByTravelDateAndTrainNumber') GROUP BY 2 UNION ALL SELECT 'ab', span_name, count(*), round(approx_quantile(duration/1e6,0.95),1) FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('OrderOtherRepository.findByAccountId','OrderOtherRepository.findAll','OrderOtherRepository.findByTravelDateAndTrainNumber') GROUP BY 2",
          "claim": "Repository methods on order-other's orders_other table are several times slower in the abnormal period than normal, with p95 up to about 2.5s."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'ab' p, metric, round(avg(value),3) avg_v FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.container.restarts') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, round(avg(value),3) FROM normal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.container.restarts') GROUP BY 1,2",
          "claim": "order-other's CPU, memory and restart metrics stay at normal levels in the abnormal period, so the slowdown is not resource saturation or a restart."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND c.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "order-other's server spans are slow when called by ui-dashboard, admin-order-service and seat-service, showing the slowdown reaches all three callers."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND p.service_name='ts-ui-dashboard' GROUP BY ALL",
          "claim": "ui-dashboard's POST orderOther/refresh calls to order-other rise from about 4ms to about 420ms p95, so user-facing refresh requests slow down."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND p.service_name='ts-admin-order-service' GROUP BY ALL",
          "claim": "admin-order-service's GET adminorder calls to order-other take about 2.2s p95, and admin-order's own server spans inherit this delay."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-admin-order-service' AND p.service_name='ts-ui-dashboard' GROUP BY ALL",
          "claim": "ui-dashboard's GET adminorder requests to admin-order-service rise to about 1s p95 (normal about 19ms)."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND p.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "seat-service's POST to order-other orders_other/tickets takes about 215ms p95, and seat's left_tickets handling inherits that delay."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-seat-service' AND p.service_name='ts-travel2-service' GROUP BY ALL",
          "claim": "travel2-service's calls to seat-service left_tickets take about 220ms p95, versus about 10ms in normal operation."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) child_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-seat-service' AND p.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "travel-plan-service's calls to seat-service left_tickets in the abnormal period are the same seat calls whose delay comes from order-other; this edge is inferred from the seat call graph."
        }
      ]
    }
  ]
}
